import { test, expect } from 'libretto/test'

test.describe("Login", () => {
  test("valid credentials", async ({ page }) => {
    await test.step("Steps 1: Open the login page", async () => {
      await page.goto('/login');
    })
    await test.step("Steps 2: Enter username `alice` and password {{env.ALICE_PASSWORD}}", async () => {
      await page.getByLabel('Username').fill('alice');
      await page.getByLabel('Password').fill(process.env.ALICE_PASSWORD!);
    })
    await test.step("Steps 3: Click \"Log in\"", async () => {
      await page.getByRole('button', { name: 'Log in' }).click();
    })
    await test.step("Expect 1: The heading \"Welcome, alice\" is visible", async () => {
      await expect(page.getByRole('heading', { name: 'Welcome, alice' })).toBeVisible();
    })
  })

  test("wrong password", async ({ page }) => {
    await test.step("Steps 1: Open the login page", async () => {
      await page.goto('/login');
    })
    await test.step("Steps 2: Enter username `alice` and password `wrong`", async () => {
      await page.getByLabel('Username').fill('alice');
      await page.getByLabel('Password').fill('wrong');
    })
    await test.step("Steps 3: Click \"Log in\"", async () => {
      await page.getByRole('button', { name: 'Log in' }).click();
    })
    await test.step("Expect 1: An alert with the text \"Invalid credentials\" is visible", async () => {
      await expect(page.getByRole('alert')).toContainText('Invalid credentials');
    })
    await test.step("Expect 2: The login form is still shown", async () => {
      await expect(page.getByLabel('Username')).toBeVisible();
      await expect(page.getByLabel('Password')).toBeVisible();
      await expect(page.getByRole('button', { name: 'Log in' })).toBeVisible();
    })
  })
})
